  const res = await fetch("/api");
  return res.json();        // if json() fails, caller's catch handles it
} catch (e) { ... }

// Version B — json error IS caught
try {
  const res = await fetch("/api");
  return await res.json();  // if json() fails, THIS catch handles it
} catch (e) { ... }
```

